mkdir -p /tmp/dandi_cache && python -c "
import h5py
import remfile
disk_cache = remfile.DiskCache('/tmp/dandi_cache')
url = 'https://api.dandiarchive.org/api/dandisets/000044/versions/draft/assets/82714afb-724f-4e2b-b102-c9c47b5cba73/download/'
rf = remfile.File(url, disk_cache=disk_cache)
f = h5py.File(rf, 'r')
def show(name, obj):
    if isinstance(obj, h5py.Dataset):
        print(f'  D {name}  shape={obj.shape}  dtype={obj.dtype}')
    else:
        print(f'  G {name}')
print('Top groups:')
for k in f.keys():
    print(f'  {k}')
print()
print('Acquisition:')
if 'acquisition' in f:
    for k in f['acquisition'].keys():
        print(f'  {k}')
print()
print('Processing:')
if 'processing' in f:
    for k in f['processing'].keys():
        print(f'  {k}')
        for k2 in f['processing'][k].keys():
            print(f'    {k2}')
print()
print('intervals:')
if 'intervals' in f:
    for k in f['intervals'].keys():
        print(f'  {k}')
print()
print('Units:')
if 'units' in f:
    print(f'  cols: {list(f[\"units\"].keys())}')
print()
print('Subject:')
if 'general' in f and 'subject' in f['general']:
    for k in f['general']['subject'].keys():
        print(f'  {k}: {f[\"general\"][\"subject\"][k][()]}')
"

